import React from "react";
import { BesuIcon } from "./BesuIcon";
import { CharonIcon } from "./CharonIcon";
import { GethIcon } from "./GethIcon";
import { GrandineIcon } from "./GrandineIcon";
import { LighthouseIcon } from "./LighthouseIcon";
import { LodestarIcon } from "./LodestarIcon";
import { NethermindIcon } from "./NethermindIcon";
import { NimbusIcon } from "./NimbusIcon";
import { PrysmIcon } from "./PrysmIcon";
import { RethIcon } from "./RethIcon";
import { TekuIcon } from "./TekuIcon";
import { CSS } from "../../../stitches.config";

export type ClientBrandIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

type ClientIconComponent = React.FC<ClientBrandIconProps>;

/** Known EL/CL/VC/DV brand icons keyed by lowercase family name. */
export const CLIENT_BRAND_ICONS: Record<string, ClientIconComponent> = {
  geth: GethIcon,
  nethermind: NethermindIcon,
  besu: BesuIcon,
  reth: RethIcon,
  grandine: GrandineIcon,
  lighthouse: LighthouseIcon,
  lodestar: LodestarIcon,
  nimbus: NimbusIcon,
  prysm: PrysmIcon,
  teku: TekuIcon,
  charon: CharonIcon,
};

export const getClientBrandIcon = (
  family: string | null | undefined,
): ClientIconComponent | null => {
  if (!family) return null;
  return CLIENT_BRAND_ICONS[family.toLowerCase()] ?? null;
};
