import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type LighthouseIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled lighthouse mark for PeerClientIcons (ships in dist). */
export const LighthouseIcon: React.FC<LighthouseIconProps> = ({
  size = 18,
  className,
  css,
  alt = "lighthouse",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

LighthouseIcon.displayName = "LighthouseIcon";
