import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type GrandineIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled grandine mark for PeerClientIcons (ships in dist). */
export const GrandineIcon: React.FC<GrandineIconProps> = ({
  size = 18,
  className,
  css,
  alt = "grandine",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

GrandineIcon.displayName = "GrandineIcon";
