import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type NimbusIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled nimbus mark for PeerClientIcons (ships in dist). */
export const NimbusIcon: React.FC<NimbusIconProps> = ({
  size = 18,
  className,
  css,
  alt = "nimbus",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

NimbusIcon.displayName = "NimbusIcon";
