import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type GethIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled geth mark for PeerClientIcons (ships in dist). */
export const GethIcon: React.FC<GethIconProps> = ({
  size = 18,
  className,
  css,
  alt = "geth",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

GethIcon.displayName = "GethIcon";
