import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type BesuIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled besu mark for PeerClientIcons (ships in dist). */
export const BesuIcon: React.FC<BesuIconProps> = ({
  size = 18,
  className,
  css,
  alt = "besu",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

BesuIcon.displayName = "BesuIcon";
