import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type PrysmIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled prysm mark for PeerClientIcons (ships in dist). */
export const PrysmIcon: React.FC<PrysmIconProps> = ({
  size = 18,
  className,
  css,
  alt = "prysm",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

PrysmIcon.displayName = "PrysmIcon";
