import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type RethIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled reth mark for PeerClientIcons (ships in dist). */
export const RethIcon: React.FC<RethIconProps> = ({
  size = 18,
  className,
  css,
  alt = "reth",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

RethIcon.displayName = "RethIcon";
